using Servicio.RetazoMarket.Business.DTOs.Descuento;
namespace Servicio.RetazoMarket.Business.Validators;public static class DescuentoValidator {public static IReadOnlyCollection<string> Validar(CrearDescuentoRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_producto,r.cantidad_minima,r.porcentaje,r.estado);public static IReadOnlyCollection<string> Validar(ActualizarDescuentoRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_producto,r.cantidad_minima,r.porcentaje,r.estado).ToList();if(r.id_descuento<=0)e.Insert(0,"El id del descuento es inválido.");return e;}public static IReadOnlyCollection<string> ValidarFiltro(DescuentoFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");if(r.cantidad_minima<=0)e.Add("La cantidad mínima del filtro debe ser positiva.");if(r.porcentaje<=0||r.porcentaje>100)e.Add("El porcentaje del filtro debe ser mayor que cero y máximo cien.");return e;}private static IReadOnlyCollection<string> Campos(int producto,int cantidad,decimal porcentaje,string? estado){var e=new List<string>();if(producto<=0)e.Add("El producto es obligatorio.");if(cantidad<=0)e.Add("La cantidad mínima debe ser mayor que cero.");if(porcentaje<=0||porcentaje>100)e.Add("El porcentaje debe ser mayor que cero y máximo cien.");if(decimal.Round(porcentaje,2)!=porcentaje)e.Add("El porcentaje admite máximo dos decimales.");if(estado?.Trim().ToUpperInvariant() is not("ACT" or "INA"))e.Add("El estado debe ser ACT o INA.");return e;}}
